-- Тема 04: правки по отчёту Codex (32 исправлений в 18 вопросах), ключи не меняются.
-- Источник: scripts/questions/092_codex_topic04_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Что делает postmaster, если какой-нибудь процесс сервера завершился аварийно?', NULL, NULL, NULL, 'Обслуживающий процесс сервера завершился аварийно, restart_after_crash = on (по умолчанию). Что делает postmaster?'),
        ('question', 'Какой процесс выполняет аутентификацию подключающегося клиента?', NULL, NULL, NULL, 'Какой процесс выполняет аутентификацию клиента при прямом подключении к серверу PostgreSQL?'),
        ('question', 'На обычной несекционированной таблице есть один включённый триггер AFTER UPDATE FOR EACH ROW без WHEN, его функция не выполняет действий, вызывающих повторное срабатывание. Одна команда UPDATE изменила 10 строк, других триггеров нет. Сколько раз он сработает?', NULL, NULL, NULL, 'На обычной несекционированной таблице есть один включённый триггер AFTER UPDATE FOR EACH ROW без WHEN (не CONSTRAINT-триггер), его функция не выполняет действий, вызывающих повторное срабатывание. Одна команда UPDATE изменила 10 строк, других триггеров нет. Сколько раз он сработает к завершению этой команды?'),
        ('question', 'Какой встроенный тип индекса обычно подходит для сравнений целых чисел как на равенство, так и на диапазон: =, <, <=, >, >=?', NULL, NULL, NULL, 'Какой встроенный тип индекса со стандартными классами операторов обычно подходит для сравнений целых чисел как на равенство, так и на диапазон: =, <, <=, >, >=?'),
        ('option', 'Что означает свойство транзакций «атомарность»?', 'Транзакция выполняется целиком или никак', NULL, 'Всё или ничего: при ошибке отменяются все изменения транзакции.', 'Изменения транзакции фиксируются целиком или целиком отменяются при её откате. Откат к точке сохранения отменяет лишь часть работы, и транзакцию можно продолжить.'),
        ('option', 'Когда стоит использовать менеджер пула соединений, например pgBouncer?', 'Чтобы включить шифрование трафика клиентов', 'Чтобы шифровать файлы таблиц на сервере', 'Шифрование трафика настраивается через SSL.', 'Пул соединений не шифрует данные на диске: для этого служат средства файловой системы или хранилища.'),
        ('option', 'Какой размер страницы данных обычно используется и как его изменить?', '8 КБ, меняется при сборке сервера', NULL, 'Размер задаётся при сборке и одинаков для всего кластера; изменить его можно только пересборкой.', 'Размер задаётся при сборке и одинаков для всего кластера; для другого размера нужна соответствующая сборка и новый кластер (initdb), а данные переносят отдельно.'),
        ('option', 'Что делает этап переписывания запроса?', 'Преобразует запрос, например раскрывает представления', 'Переписывает дерево запроса по системе правил', NULL, NULL),
        ('option', 'Обслуживающий процесс сервера завершился аварийно, restart_after_crash = on (по умолчанию). Что делает postmaster?', 'Останавливает сервер до запуска администратором', NULL, 'При настройке по умолчанию (restart_after_crash = on) сервер восстанавливается автоматически, без участия администратора.', 'Так было бы при restart_after_crash = off.'),
        ('option', 'Обслуживающий процесс сервера завершился аварийно, restart_after_crash = on (по умолчанию). Что делает postmaster?', 'Записывает ошибку и продолжает работу без этого процесса', NULL, 'Сбой не игнорируется: процесс перезапускается, а при угрозе повреждения общей памяти сервер переинициализируется целиком.', 'Аварийное завершение не игнорируется: остальные процессы завершаются, и сервер восстанавливается.'),
        ('option', 'Обслуживающий процесс сервера завершился аварийно, restart_after_crash = on (по умолчанию). Что делает postmaster?', 'Перезапускает процесс, а при угрозе общей памяти — весь сервер', 'Завершает остальные процессы и запускает восстановление', 'Так postmaster «присматривает» за процессами; восстановление после сбоя работает при restart_after_crash = on (по умолчанию).', 'Аварийно завершившийся процесс мог повредить общую память, поэтому postmaster завершает остальные процессы, заново инициализирует общую память и запускает восстановление по журналу.'),
        ('option', 'Какой процесс выполняет аутентификацию клиента при прямом подключении к серверу PostgreSQL?', 'Библиотека libpq на стороне клиента', 'Клиентская библиотека libpq', NULL, NULL),
        ('option', 'Какой процесс выполняет аутентификацию клиента при прямом подключении к серверу PostgreSQL?', 'Процесс postmaster при приёме подключения', 'Главный процесс postmaster', NULL, NULL),
        ('option', 'Какой процесс выполняет аутентификацию клиента при прямом подключении к серверу PostgreSQL?', 'Обслуживающий процесс, порождённый для клиента', 'Обслуживающий процесс backend', 'После этого клиент общается уже с ним.', 'postmaster порождает его для клиента, после чего клиент общается уже с ним.'),
        ('option', 'Какой процесс выполняет аутентификацию клиента при прямом подключении к серверу PostgreSQL?', 'Менеджер пула соединений pgBouncer', 'Отдельный процесс аутентификации', 'Пул необязателен, аутентификацию выполняет сервер.', 'Отдельного процесса аутентификации в PostgreSQL нет: её выполняет обслуживающий процесс, порождённый для клиента.'),
        ('option', 'Что нужно учитывать приложению, работающему через менеджер пула соединений в режиме пула транзакций (например, PgBouncer)?', 'Число обслуживающих процессов растёт вместе с числом клиентов', 'Каждому клиенту выделяется свой backend на всё время сеанса', 'Число серверных процессов определяется числом серверных соединений пула и его лимитами: оно не обязано ни совпадать с числом клиентов, ни быть постоянным.', 'В режиме пула транзакций backend закрепляется за клиентом только на время транзакции; число серверных процессов определяется лимитами пула.'),
        ('option', 'В базе определена функция app.add_tax(numeric), возвращающая numeric. Что делает запрос SELECT app.add_tax(100);?', 'Обязательно добавляет 100 строк в таблицу app', 'Добавляет 100 строк в таблицу с именем app', NULL, NULL),
        ('option', 'В базе определена функция app.add_tax(numeric), возвращающая numeric. Что делает запрос SELECT app.add_tax(100);?', 'Вызывает функцию с аргументом 100 и выводит результат', 'Вызывает функцию с аргументом 100', 'Вызов функции используется как выражение в SELECT.', 'Вызов функции используется как выражение в SELECT, и клиент получает её результат.'),
        ('option', 'Какие формы результата может иметь пользовательская функция PostgreSQL при соответствующем объявлении?', 'Целое число, используемое как код завершения ОС', 'Два независимых набора строк за один вызов', 'Функции SQL не ограничены моделью кодов завершения процессов.', 'Функция возвращает результат одной объявленной формы: SETOF и RETURNS TABLE дают один набор строк, а не несколько независимых.'),
        ('option', 'Что такое триггер в PostgreSQL?', 'Подпрограмма, которая срабатывает исключительно по расписанию часов', 'Объект, запускающий задание по заданному расписанию', 'Триггеры привязаны к событиям базы, а не к расписанию ОС.', 'Триггеры привязаны к событиям в базе, а запуск по расписанию — задача планировщика заданий.'),
        ('option', 'Какие утверждения об обычных триггерах таблиц верны?', 'Для любой проверки NOT NULL обязательно писать свой триггер', 'NOT NULL в PostgreSQL реализован встроенным триггером', 'NOT NULL обеспечивается встроенным ограничением.', 'NOT NULL проверяется самим ограничением, без триггеров; встроенные триггеры используют внешние ключи.'),
        ('option', 'Какие утверждения об обычных триггерах таблиц верны?', 'Триггер срабатывает после ручной команды CALL', 'Команда CALL — событие обычного табличного триггера', 'Срабатывание определяется событием, указанным при создании триггера.', 'События обычного триггера — INSERT, UPDATE, DELETE и TRUNCATE. CALL вызывает процедуру, а её команды изменения таблицы могут вызвать триггер косвенно.'),
        ('option', 'Для чего в базе данных нужен индекс?', 'Для обязательного хранения второй полной копии всех столбцов таблицы', 'Для хранения резервной копии строк таблицы', 'Индекс не обязан содержать все столбцы и не является резервной копией таблицы.', 'Индекс не является резервной копией таблицы и не обязан содержать все её столбцы.'),
        ('option', 'Для чего в базе данных нужен индекс?', 'Для гарантированного ускорения каждого запроса без дополнительных затрат', 'Для ускорения записи новых строк в таблицу', 'Индекс полезен не всегда, занимает место и требует обслуживания.', 'Наоборот, каждый индекс замедляет запись: его тоже нужно обновлять.'),
        ('option', 'Для чего в базе данных нужен индекс?', 'Для дополнительного пути доступа к нужным строкам', 'Как дополнительный путь доступа к строкам', NULL, NULL),
        ('option', 'Для чего в базе данных нужен индекс?', 'Для замены любых ограничений целостности', 'Для сжатия данных таблицы на диске', 'Например, индекс сам по себе не заменяет внешний ключ или CHECK.', 'Индекс не сжимает таблицу, а занимает дополнительное место.'),
        ('option', 'На столбце есть подходящий индекс, но PostgreSQL выбирает последовательное сканирование таблицы. Обязательно ли это ошибка?', 'Да: любой существующий индекс обязан использоваться во всех запросах', 'Да: при подходящем индексе план должен его использовать', 'Планировщик выбирает план, а не использует индекс только из-за его наличия.', 'Планировщик сравнивает стоимость планов: при чтении большой доли таблицы последовательное сканирование может быть дешевле.'),
        ('option', 'На столбце есть подходящий индекс, но PostgreSQL выбирает последовательное сканирование таблицы. Обязательно ли это ошибка?', 'Да: после создания любого индекса сервер нужно перезапустить', 'Да: значит, индекс повреждён и его нужно перестроить', 'Штатное создание индекса не требует перезапуска.', 'Выбор плана зависит от оценок стоимости; исправный индекс тоже может не использоваться.'),
        ('option', 'Какой встроенный тип индекса со стандартными классами операторов обычно подходит для сравнений целых чисел как на равенство, так и на диапазон: =, <, <=, >, >=?', 'Для диапазонов индексы использовать нельзя', 'SP-GiST', 'Диапазонный поиск — обычное применение B-tree.', 'SP-GiST со стандартными классами операторов рассчитан на точки, текст, сетевые адреса и диапазонные типы, а не на целые числа.'),
        ('option', 'Как команда PREPARE q(integer) AS SELECT * FROM t WHERE id = $1 соотносится со стандартом SQL?', 'Описана в стандарте SQL и работает везде одинаково', 'Это стандартная форма SQL PREPARE без изменений синтаксиса', 'Синтаксис подготовки операторов в разных СУБД различается; приложения обычно готовят операторы через драйвер.', 'В стандарте PREPARE есть только для встроенного SQL и с другим синтаксисом.'),
        ('option', 'Что означает свойство транзакций «изоляция»?', 'Транзакции выполняются строго по очереди, одна за другой', 'Транзакции выполняются последовательно, одна за другой', NULL, NULL),
        ('explanation', 'Сеанс 1 выполнил BEGIN и вставил новую строку, но COMMIT ещё не выполнил. Кто видит эту строку?', NULL, NULL, 'После COMMIT видимость строки для других транзакций зависит от их снимков: транзакция Read Committed увидит её в следующей команде, а транзакция Repeatable Read с уже взятым снимком — нет. Если сеанс 1 выполнит ROLLBACK, строку так никто и не увидит.', 'После COMMIT видимость строки для других транзакций зависит от их снимков: транзакция Read Committed увидит её в следующей команде, а транзакция Repeatable Read с уже взятым снимком — нет. Если сеанс 1 выполнит ROLLBACK, другие сеансы эту строку так и не увидят.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
